def reminder(name, days):
    return f"Hi {name}, invoice due in {days} days."

for n in ["Ava", "Ben"]:
    print(reminder(n, 3))

prices = {"cut": 25, "beard": 15, "wash": 10}
for service, price in prices.items():
    print(service, "->", price)
print("keys:", list(prices.keys()))

def to_int(text):
    try:
        return int(text)
    except ValueError:
        return None

print(to_int("42"))
print(to_int("forty-two"))

